classdef TestMeshAgainstLegacy < LdemTestCase
    %TESTMESHAGAINSTLEGACY  The new mesh equals the one built by the legacy code.
    %
    %   Compares ldem.mesh.buildMesh with the node coordinates, supports,
    %   masses, connectivity and bar geometry stored in the golden-master
    %   fixtures (generated by legacy/main1.m). No simulation is run, so the
    %   test is fast.
    %
    %   See also TestFixtures, generateReference.

    properties (TestParameter)
        caseName = {'tension101_elastic', 'tension101_damage', 'bending102'}
    end

    methods (Test, TestTags = {'Regression'})
        function meshMatchesLegacy(testCase, caseName)
            fixture = load(fullfile(testCase.RepoRoot, 'tests', 'fixtures', caseName + ".mat"));
            s = fixture.state;
            params = TestMeshAgainstLegacy.parametersOf(fixture.caseDef);

            mesh = ldem.mesh.buildMesh(params);

            tight = {'RelTol', 1e-14, 'AbsTol', 1e-18};

            testCase.verifyEqual(params.nNodes, s.NNT, 'Node count differs.');
            testCase.verifyEqual(size(mesh.bars, 1), s.NBT, 'Bar count differs.');

            % Initial coordinates (legacy U0, V0, W0).
            testCase.verifyEqual(mesh.nodes0, [s.U0(:), s.V0(:), s.W0(:)], tight{:});

            % Supports (legacy BDX, BDY, BDZ).
            legacyFixed = [s.BDX(:), s.BDY(:), s.BDZ(:)] ~= 0;
            testCase.verifyEqual(mesh.fixed, legacyFixed, 'Supports differ.');

            % Lumped masses (legacy MAS).
            testCase.verifyEqual(mesh.mass, s.MAS(:), tight{:});

            % Connectivity (legacy CN is [start1 end1 start2 end2 ...]).
            testCase.verifyEqual(mesh.bars, reshape(s.CN, 2, []).', 'Connectivity differs.');

            % Bar geometry (legacy LI, XB, YB, ZB).
            testCase.verifyEqual(mesh.barLength, s.LI(:), tight{:});
            testCase.verifyEqual(mesh.barCentres, [s.XB(:), s.YB(:), s.ZB(:)], tight{:});
        end

        function timeIntegrationSettingsMatchLegacy(testCase, caseName)
            fixture = load(fullfile(testCase.RepoRoot, 'tests', 'fixtures', caseName + ".mat"));
            params = TestMeshAgainstLegacy.parametersOf(fixture.caseDef);
            testCase.verifyEqual(params.nSteps, double(fixture.state.NSTEP));
            testCase.verifyEqual(params.dt, fixture.state.DT);
        end

        function stabilityCheckAgreesWithLegacyCriterion(testCase, caseName)
            % Legacy NAYFES0 stops when min(LI)/sqrt(E/rho) < DT.
            fixture = load(fullfile(testCase.RepoRoot, 'tests', 'fixtures', caseName + ".mat"));
            params = TestMeshAgainstLegacy.parametersOf(fixture.caseDef);
            mesh = ldem.mesh.buildMesh(params);
            legacyCritical = min(fixture.state.LI) / sqrt(params.youngModulus / params.density);
            testCase.verifyEqual(ldem.solver.checkStability(mesh.barLength, params), ...
                legacyCritical, 'RelTol', 1e-12);
        end
    end

    methods (Static, Access = private)
        function params = parametersOf(c)
            %PARAMETERSOF  Build ldem.Parameters from a reference-case definition.
            params = ldem.Parameters( ...
                testId = c.test, ...
                seed = c.seed, ...
                moduleLength = c.moduleLength, ...
                nModules = c.modules, ...
                dampingInitial = c.damping1, ...
                dampingFinal = c.damping2, ...
                dampingSwitchTime = c.dampingSwitchTime, ...
                constitutiveDamping = c.con, ...
                dt = c.dt, ...
                totalTime = c.nSteps * c.dt, ...
                controlNodes = c.controlNodes, ...
                youngModulus = c.youngModulus, ...
                density = c.density, ...
                poissonRatio = c.poisson, ...
                fractureEnergy = c.fractureEnergy, ...
                criticalDistance = c.criticalDistance);
        end
    end
end
